-- Allow cooked Indian dishes from the Indian Nutrient Databank (INDB, 2024,
-- CC BY) in the food master alongside IFCT 2017 ingredients. Data is loaded by
-- backend/scripts/data/indb-2024.sql (generated by build-indb-sql.py).
alter table public.foods drop constraint if exists foods_source_check;
alter table public.foods
  add constraint foods_source_check
  check (source = any (array['IFCT-2017', 'INDB-2024', 'USDA-FDC', 'FAO', 'CUSTOM-APPROVED']));
